 53→
 54→    // Review action mutation
 55→    const reviewAction = useReviewAction();
 56→
 57→    // Entity data
 58→    const { data: entities } = useEntityListByBatch(batchId ?? '');
 59→    const entityAction = useEntityAction();
 60→
 61→    // Audit log
 62→    const { data: auditData } = useAuditLog(1, 20, 'criteria');
 63→
 64→    function handleAction(criterionId: string, action: ReviewActionRequest) {
 65→        reviewAction.mutate({ criteriaId: criterionId, ...action });
 66→    }
 67→
 68→    function handleEntityAction(entityId: string, action: EntityActionRequest) {
 69→        entityAction.mutate({ entityId, ...action });
 70→    }
 71→
 72→    function handleCriterionClick(criterion: Criterion) {
 73→        // Toggle: clicking the same criterion deselects it
 74→        if (activeCriterion?.id === criterion.id) {
 75→            setActiveCriterion(null);
 76→        } else {
 77→            setActiveCriterion(criterion);
 78→        }
 79→    }
 80→
 81→    const reviewedCount = criteria?.filter((c) => c.review_status !== null).length ?? 0;
 82→    const totalCount = criteria?.length ?? 0;
 83→    const progressPercent = totalCount > 0 ? Math.round((reviewedCount / totalCount) * 100) : 0;
 84→
 85→    // Group entities by criteria_id
 86→    const groupedEntities: Record<string, EntityResponse[]> = {};
 87→    if (entities) {
 88→        for (const entity of entities) {
 89→            if (!groupedEntities[entity.criteria_id]) {
 90→                groupedEntities[entity.criteria_id] = [];
 91→            }
 92→            groupedEntities[entity.criteria_id]?.push(entity);
 93→        }
 94→    }
 95→
 96→    // Client-side filtering
 97→    const filteredCriteria = useMemo(() => {
 98→        if (!criteria) return [];
 99→        return criteria.filter((c) => {
100→            // Text search (case-insensitive)
101→            if (debouncedSearch && !c.text.toLowerCase().includes(debouncedSearch.toLowerCase())) {
102→                return false;
103→            }
104→            // Status filter
105→            if (statusFilter !== 'all') {
106→                const isReviewed = c.review_status !== null;
107→                if (statusFilter === 'reviewed' && !isReviewed) return false;
108→                if (statusFilter === 'pending' && isReviewed) return false;
109→            }
110→            // Type filter
111→            if (typeFilter !== 'all' && c.criteria_type !== typeFilter) {
112→                return false;
113→            }
114→            // Confidence filter (high>=0.85, medium>=0.7, low<0.7)
115→            if (confidenceFilter !== 'all') {
116→                if (confidenceFilter === 'high' && c.confidence < 0.85) return false;
117→                if (confidenceFilter === 'medium' && (c.confidence < 0.7 || c.confidence >= 0.85))
118→                    return false;
119→                if (confidenceFilter === 'low' && c.confidence >= 0.7) return false;
120→            }
121→            return true;
122→        });
123→    }, [criteria, debouncedSearch, statusFilter, typeFilter, confidenceFilter]);
124→
125→    // Section grouping with pending-first sort
126→    const { uncategorizedCriteria, inclusionCriteria, exclusionCriteria } = useMemo(() => {
127→        const uncategorized: Criterion[] = [];
128→        const inclusion: Criterion[] = [];
129→        const exclusion: Criterion[] = [];
130→
131→        for (const c of filteredCriteria) {
132→            if (
133→                !c.criteria_type ||
134→                (c.criteria_type !== 'inclusion' && c.criteria_type !== 'exclusion')
135→            ) {
136→                uncategorized.push(c);
137→            } else if (c.criteria_type === 'inclusion') {
138→                inclusion.push(c);
139→            } else {
140→                exclusion.push(c);
141→            }
142→        }
143→
144→        const sortFn = (a: Criterion, b: Criterion) => {
145→            const aPending = a.review_status === null;
146→            const bPending = b.review_status === null;
147→            if (aPending && !bPending) return -1;
148→            if (!aPending && bPending) return 1;
149→            return 0;
150→        };
151→        uncategorized.sort(sortFn);
152→        inclusion.sort(sortFn);
153→        exclusion.sort(sortFn);
154→
155→        return {
156→            uncategorizedCriteria: uncategorized,
157→            inclusionCriteria: inclusion,
158→            exclusionCriteria: exclusion,
159→        };
160→    }, [filteredCriteria]);
161→
162→    const countReviewed = (list: Criterion[]) =>
163→        list.filter((c) => c.review_status !== null).length;
164→
165→    if (criteriaLoading) {
166→        return (
167→            <div className="flex items-center justify-center h-screen">
168→                <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
169→            </div>
170→        );
171→    }
172→
173→    if (criteriaError) {
174→        return (
175→            <div className="container mx-auto p-6">
176→                <Link
177→                    to="/reviews"
178→                    className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground mb-6"
179→                >
180→                    <ArrowLeft className="h-4 w-4 mr-1" />
181→                    Back to Review Queue
182→                </Link>
183→                <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-6 text-center">
184→                    <p className="text-destructive">
185→                        Failed to load criteria: {criteriaError.message}
186→                    </p>
187→                </div>
188→            </div>
189→        );
190→    }
191→
192→    return (
193→        <div className="h-screen flex flex-col">
194→            <PanelGroup direction="horizontal" className="flex-1">
195→                {/* Left panel: PDF Viewer */}
196→                <Panel defaultSize={50} minSize={30}>
197→                    <div className="h-full flex flex-col">
198→                        <div className="px-4 py-2 border-b bg-card">
199→                            <h2 className="text-sm font-medium text-muted-foreground">
200→                                Protocol PDF
201→                            </h2>
202→                        </div>
203→                        <div className="flex-1 overflow-hidden">
204→                            {pdfLoading ? (
205→                                <div className="flex items-center justify-center h-full">
206→                                    <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
207→                                </div>
208→                            ) : pdfData?.url ? (
209→                                <PdfViewer
210→                                    url={pdfData.url}
211→                                    targetPage={activeCriterion?.page_number ?? null}
212→                                    highlightText={activeCriterion?.text ?? null}
213→                                />
214→                            ) : (
215→                                <div className="flex items-center justify-center h-full">
216→                                    <p className="text-muted-foreground">No PDF available</p>
217→                                </div>
218→                            )}
219→                        </div>
220→                    </div>
221→                </Panel>
222→
223→                <PanelResizeHandle className="w-1 bg-border hover:bg-primary/20 transition-colors" />
224→
225→                {/* Right panel: Criteria and Entities Review */}
226→                <Panel defaultSize={50} minSize={30}>
227→                    <div className="h-full overflow-auto">
228→                        {/* Header */}
229→                        <div className="sticky top-0 z-10 bg-card border-b px-4 py-3 space-y-3">
230→                            <div className="flex items-center justify-between">
231→                                <Link
232→                                    to="/reviews"
233→                                    className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground"
234→                                >
235→                                    <ArrowLeft className="h-4 w-4 mr-1" />
236→                                    Review Queue
237→                                </Link>
238→                                {batch && (
239→                                    <span
240→                                        className={cn(
241→                                            'inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium',
242→                                            batch.status === 'approved'
243→                                                ? 'bg-green-100 text-green-800'
244→                                                : batch.status === 'rejected'
245→                                                  ? 'bg-red-100 text-red-800'
246→                                                  : batch.status === 'in_progress'
247→                                                    ? 'bg-blue-100 text-blue-800'
248→                                                    : 'bg-yellow-100 text-yellow-800'
249→                                        )}
250→                                    >
251→                                        {batch.status.replace(/_/g, ' ')}
252→                                    </span>
253→                                )}
254→                            </div>
255→
256→                            {/* Progress bar */}
257→                            <div>
258→                                <div className="flex items-center justify-between mb-1">
259→                                    <span className="text-sm text-muted-foreground">
260→                                        {reviewedCount}/{totalCount} criteria reviewed
261→                                    </span>
262→                                    <span className="text-sm font-medium">{progressPercent}%</span>
263→                                </div>
264→                                <div className="h-2 w-full rounded-full bg-muted overflow-hidden">
265→                                    <div
266→                                        className={cn(
267→                                            'h-full rounded-full transition-all',
268→                                            progressPercent === 100 ? 'bg-green-500' : 'bg-blue-500'
269→                                        )}
270→                                        style={{ width: `${progressPercent}%` }}
271→                                    />
272→                                </div>
273→                            </div>
274→                        </div>
275→
276→                        {/* Tabs for Criteria and Entities */}
277→                        <Tabs.Root value={activeTab} onValueChange={setActiveTab}>
278→                            <Tabs.List className="flex border-b bg-card px-4">
279→                                <Tabs.Trigger
280→                                    value="criteria"
281→                                    className={cn(
282→                                        'px-4 py-2 text-sm font-medium border-b-2 transition-colors',
283→                                        activeTab === 'criteria'
284→                                            ? 'border-primary text-foreground'
285→                                            : 'border-transparent text-muted-foreground hover:text-foreground'
286→                                    )}
287→                                >
288→                                    Criteria
289→                                </Tabs.Trigger>
290→                                <Tabs.Trigger
291→                                    value="entities"
292→                                    className={cn(
293→                                        'px-4 py-2 text-sm font-medium border-b-2 transition-colors',
294→                                        activeTab === 'entities'
295→                                            ? 'border-primary text-foreground'
296→                                            : 'border-transparent text-muted-foreground hover:text-foreground'
297→                                    )}
298→                                >
299→                                    Entities
300→                                </Tabs.Trigger>
301→                            </Tabs.List>
302→
303→                            {/* Criteria Tab Content */}
304→                            <Tabs.Content value="criteria" className="">
305→                                {/* Sticky filter bar */}
306→                                <div className="sticky top-0 z-10 bg-card border-b px-4 py-3">
307→                                    <div className="flex items-center gap-3 flex-wrap">
308→                                        <div className="relative flex-1 min-w-[200px]">
309→                                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
310→                                            <input
311→                                                type="text"
312→                                                value={searchText}
313→                                                onChange={(e) => setSearchText(e.target.value)}
314→                                                placeholder="Search criteria..."
315→                                                className="w-full rounded-md border border-input bg-background pl-9 pr-3 py-2 text-sm"
316→                                            />
317→                                        </div>
318→                                        <select
319→                                            value={statusFilter}
320→                                            onChange={(e) => setStatusFilter(e.target.value)}
321→                                            className="rounded-md border border-input bg-background px-3 py-2 text-sm"
322→                                        >
323→                                            <option value="all">All Status</option>
324→                                            <option value="pending">Pending</option>
325→                                            <option value="reviewed">Reviewed</option>
326→                                        </select>
327→                                        <select
328→                                            value={typeFilter}
329→                                            onChange={(e) => setTypeFilter(e.target.value)}
330→                                            className="rounded-md border border-input bg-background px-3 py-2 text-sm"
331→                                        >
332→                                            <option value="all">All Types</option>
333→                                            <option value="inclusion">Inclusion</option>
334→                                            <option value="exclusion">Exclusion</option>
335→                                        </select>
336→                                        <select
337→                                            value={confidenceFilter}
338→                                            onChange={(e) => setConfidenceFilter(e.target.value)}
339→                                            className="rounded-md border border-input bg-background px-3 py-2 text-sm"
340→                                        >
341→                                            <option value="all">All Confidence</option>
342→                                            <option value="high">High (≥85%)</option>
343→                                            <option value="medium">Medium (70-84%)</option>
344→                                            <option value="low">Low (&lt;70%)</option>
345→                                        </select>
346→                                    </div>
347→                                </div>
348→
349→                                {/* Criteria sections */}
350→                                <div className="p-4 space-y-6">
351→                                    {/* To Be Sorted — appears at top if any uncategorized criteria exist */}
352→                                    {uncategorizedCriteria.length > 0 && (
353→                                        <section>
354→                                            <h2 className="text-lg font-bold mb-3 text-foreground">
355→                                                To Be Sorted ({countReviewed(uncategorizedCriteria)}
356→                                                /{uncategorizedCriteria.length} reviewed)
357→                                            </h2>
358→                                            <div className="space-y-4">
359→                                                {uncategorizedCriteria.map((c) => (
360→                                                    <CriterionCard
361→                                                        key={c.id}
362→                                                        criterion={c}
363→                                                        onAction={handleAction}
364→                                                        isSubmitting={reviewAction.isPending}
365→                                                        onCriterionClick={handleCriterionClick}
366→                                                        isActive={activeCriterion?.id === c.id}
367→                                                        pdfUrl={pdfData?.url}
368→                                                    />
369→                                                ))}
370→                                            </div>
371→                                        </section>
372→                                    )}
373→
374→                                    {/* Inclusion Criteria section */}
375→                                    {inclusionCriteria.length > 0 && (
376→                                        <section>
377→                                            <h2 className="text-lg font-bold mb-3 text-foreground">
378→                                                Inclusion Criteria (
379→                                                {countReviewed(inclusionCriteria)}/
380→                                                {inclusionCriteria.length} reviewed)
381→                                            </h2>
382→                                            <div className="space-y-4">
383→                                                {inclusionCriteria.map((c) => (
384→                                                    <CriterionCard
385→                                                        key={c.id}
386→                                                        criterion={c}
387→                                                        onAction={handleAction}
388→                                                        isSubmitting={reviewAction.isPending}
389→                                                        onCriterionClick={handleCriterionClick}
390→                                                        isActive={activeCriterion?.id === c.id}
391→                                                        pdfUrl={pdfData?.url}
392→                                                    />
393→                                                ))}
394→                                            </div>
395→                                        </section>
396→                                    )}
397→
398→                                    {/* Exclusion Criteria section */}
399→                                    {exclusionCriteria.length > 0 && (
400→                                        <section>
401→                                            <h2 className="text-lg font-bold mb-3 text-foreground">
402→                                                Exclusion Criteria (
403→                                                {countReviewed(exclusionCriteria)}/
404→                                                {exclusionCriteria.length} reviewed)
405→                                            </h2>
406→                                            <div className="space-y-4">
407→                                                {exclusionCriteria.map((c) => (
408→                                                    <CriterionCard
409→                                                        key={c.id}
410→                                                        criterion={c}
411→                                                        onAction={handleAction}
412→                                                        isSubmitting={reviewAction.isPending}
413→                                                        onCriterionClick={handleCriterionClick}
414→                                                        isActive={activeCriterion?.id === c.id}
415→                                                        pdfUrl={pdfData?.url}
416→                                                    />
417→                                                ))}
418→                                            </div>
419→                                        </section>
420→                                    )}
421→
422→                                    {/* Empty state when filters match nothing */}
423→                                    {filteredCriteria.length === 0 &&
424→                                        criteria &&
425→                                        criteria.length > 0 && (
426→                                            <div className="text-center py-8">
427→                                                <p className="text-muted-foreground">
428→                                                    No criteria match your filters
429→                                                </p>
430→                                            </div>
431→                                        )}
432→
433→                                    {/* Original empty state when no criteria at all */}
434→                                    {(!criteria || criteria.length === 0) && (
435→                                        <div className="text-center py-8">
436→                                            <p className="text-muted-foreground">
437→                                                No criteria found for this batch
438→                                            </p>
439→                                        </div>
440→                                    )}
441→
442→                                    {/* Audit trail section */}
443→                                    <div className="mt-6 border-t pt-4">
444→                                        <button
445→                                            type="button"
446→                                            className="flex items-center gap-2 text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
447→                                            onClick={() => setAuditOpen(!auditOpen)}
448→                                        >
449→                                            {auditOpen ? (
450→                                                <ChevronUp className="h-4 w-4" />
451→                                            ) : (
452→                                                <ChevronDown className="h-4 w-4" />
453→                                            )}
454→                                            Audit Trail
455→                                        </button>
456→
457→                                        {auditOpen && auditData && (
458→                                            <div className="mt-3 space-y-2">
459→                                                {auditData.items.length === 0 ? (
460→                                                    <p className="text-sm text-muted-foreground">
461→                                                        No audit entries yet
462→                                                    </p>
463→                                                ) : (
464→                                                    auditData.items.map((entry) => (
465→                                                        <div
466→                                                            key={entry.id}
467→                                                            className="flex items-start gap-3 rounded-md border bg-muted/30 px-3 py-2 text-xs"
468→                                                        >
469→                                                            <span className="text-muted-foreground whitespace-nowrap">
470→                                                                {formatTimestamp(entry.created_at)}
471→                                                            </span>
472→                                                            <span className="font-medium">
473→                                                                {entry.event_type}
474→                                                            </span>
475→                                                            {entry.actor_id && (
476→                                                                <span className="text-muted-foreground">
477→                                                                    by {entry.actor_id}
478→                                                                </span>
479→                                                            )}
480→                                                            {entry.target_type &&
481→                                                                entry.target_id && (
482→                                                                    <span className="text-muted-foreground">
483→                                                                        on {entry.target_type}:
484→                                                                        {entry.target_id.slice(
485→                                                                            0,
486→                                                                            8
487→                                                                        )}
488→                                                                    </span>
489→                                                                )}
490→                                                        </div>
491→                                                    ))
492→                                                )}
493→                                            </div>
494→                                        )}
495→                                    </div>
496→                                </div>
497→                            </Tabs.Content>
498→
499→                            {/* Entities Tab Content */}
500→                            <Tabs.Content value="entities" className="p-4">
501→                                {entities && entities.length > 0 ? (
502→                                    <div className="space-y-6">
503→                                        {Object.entries(groupedEntities).map(
504→                                            ([criteriaId, criteriaEntities]) =>
505→                                                criteriaEntities ? (
506→                                                    <div key={criteriaId} className="space-y-3">
507→                                                        <h3 className="text-sm font-medium text-muted-foreground">
508→                                                            Criterion: {criteriaId.slice(0, 8)}...
509→                                                        </h3>
510→                                                        {criteriaEntities.map((entity) => (
511→                                                            <EntityCard
512→                                                                key={entity.id}
513→                                                                entity={entity}
514→                                                                onAction={handleEntityAction}
515→                                                                isSubmitting={
516→                                                                    entityAction.isPending
517→                                                                }
518→                                                            />
519→                                                        ))}
520→                                                    </div>
521→                                                ) : null
522→                                        )}
523→                                    </div>
524→                                ) : (
525→                                    <div className="text-center py-8">
526→                                        <p className="text-muted-foreground">
527→                                            No entities found for this batch
528→                                        </p>
529→                                    </div>
530→                                )}
531→                            </Tabs.Content>
532→                        </Tabs.Root>
533→                    </div>
534→                </Panel>
535→            </PanelGroup>
536→        </div>
537→    );
538→}
