484→                                                                        {entry.target_id.slice(
485→                                                                            0,
486→                                                                            8
487→                                                                        )}
488→                                                                    </span>
489→                                                                )}
490→                                                        </div>
491→                                                    ))
492→                                                )}
493→                                            </div>
494→                                        )}
