  1→import { ChevronLeft, ChevronRight, FileSpreadsheet, Loader2 } from 'lucide-react';
  2→import { useState } from 'react';
  3→
  4→import { CriteriaTable } from '../components/criteria-table/CriteriaTable';
  5→import { columns } from '../components/criteria-table/columns';
  6→import { FilterBar } from '../components/criteria-table/filters';
  7→import { Button } from '../components/ui/Button';
  8→import { useCriteriaSpreadsheet } from '../hooks/useCriteriaSpreadsheet';
  9→import { useProtocolList } from '../hooks/useProtocols';
 10→
 11→export default function CriteriaSpreadsheet() {
 12→    const [page, setPage] = useState(1);
 13→    const [protocolId, setProtocolId] = useState('');
 14→    const [criteriaType, setCriteriaType] = useState('');
 15→    const [category, setCategory] = useState('');
 16→    const [minConfidence, setMinConfidence] = useState('');
 17→
 18→    const { data: protocolData } = useProtocolList(1, 100);
 19→    const protocols = (protocolData?.items ?? []).map((p) => ({ id: p.id, title: p.title }));
 20→
 21→    const { data, isLoading, error } = useCriteriaSpreadsheet({
 22→        page,
 23→        pageSize: 50,
 24→        protocolId: protocolId || undefined,
 25→        criteriaType: criteriaType || undefined,
 26→        category: category || undefined,
 27→        minConfidence: minConfidence ? Number.parseFloat(minConfidence) : undefined,
 28→        sortBy: 'confidence',
 29→        sortOrder: 'desc',
 30→    });
 31→
 32→    const totalCriteria = data?.total ?? 0;
 33→    const totalPages = data?.pages ?? 1;
 34→    const items = data?.items ?? [];
 35→
 36→    // Stats
 37→    const inclusionCount = items.filter((i) => i.criteria_type === 'inclusion').length;
 38→    const exclusionCount = items.filter((i) => i.criteria_type === 'exclusion').length;
 39→    const avgConfidence =
 40→        items.length > 0 ? items.reduce((s, i) => s + i.confidence, 0) / items.length : 0;
 41→    const groundedCount = items.filter((i) => i.entities.some((e) => e.grounding_code)).length;
 42→
 43→    return (
 44→        <div className="container mx-auto p-6 space-y-6">
 45→            {/* Header */}
 46→            <header className="flex items-center justify-between">
 47→                <div className="flex items-center gap-3">
 48→                    <FileSpreadsheet className="h-7 w-7 text-blue-600" />
 49→                    <div>
 50→                        <h1 className="text-2xl font-bold text-foreground">Structured Criteria</h1>
 51→                        <p className="text-sm text-muted-foreground">
 52→                            Browse and filter extracted eligibility criteria across all protocols
 53→                        </p>
 54→                    </div>
 55→                </div>
 56→                <div className="text-sm text-muted-foreground tabular-nums">
 57→                    {totalCriteria} criteria total
 58→                </div>
 59→            </header>
 60→
 61→            {/* Stats summary */}
 62→            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
 63→                <div className="rounded-lg border bg-card p-4">
 64→                    <div className="text-2xl font-bold text-emerald-600 tabular-nums">
 65→                        {inclusionCount}
 66→                    </div>
 67→                    <div className="text-xs text-muted-foreground">Inclusion (this page)</div>
 68→                </div>
 69→                <div className="rounded-lg border bg-card p-4">
 70→                    <div className="text-2xl font-bold text-red-600 tabular-nums">
 71→                        {exclusionCount}
 72→                    </div>
 73→                    <div className="text-xs text-muted-foreground">Exclusion (this page)</div>
 74→                </div>
 75→                <div className="rounded-lg border bg-card p-4">
 76→                    <div className="text-2xl font-bold text-blue-600 tabular-nums">
 77→                        {Math.round(avgConfidence * 100)}%
 78→                    </div>
 79→                    <div className="text-xs text-muted-foreground">Avg confidence</div>
 80→                </div>
 81→                <div className="rounded-lg border bg-card p-4">
 82→                    <div className="text-2xl font-bold text-purple-600 tabular-nums">
 83→                        {groundedCount}
 84→                    </div>
 85→                    <div className="text-xs text-muted-foreground">With grounding</div>
 86→                </div>
 87→            </div>
 88→
 89→            {/* Filters */}
 90→            <div className="rounded-lg border bg-card p-4">
 91→                <FilterBar
 92→                    protocolId={protocolId}
 93→                    setProtocolId={(v) => {
 94→                        setProtocolId(v);
 95→                        setPage(1);
 96→                    }}
 97→                    protocols={protocols}
 98→                    criteriaType={criteriaType}
 99→                    setCriteriaType={(v) => {
100→                        setCriteriaType(v);
101→                        setPage(1);
102→                    }}
103→                    category={category}
104→                    setCategory={(v) => {
105→                        setCategory(v);
106→                        setPage(1);
107→                    }}
108→                    minConfidence={minConfidence}
109→                    setMinConfidence={(v) => {
110→                        setMinConfidence(v);
111→                        setPage(1);
112→                    }}
113→                />
114→            </div>
115→
116→            {/* Table */}
117→            {isLoading ? (
118→                <div className="flex items-center justify-center py-20">
119→                    <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
120→                    <span className="ml-3 text-muted-foreground">Loading criteria...</span>
121→                </div>
122→            ) : error ? (
123→                <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-6 text-center">
124→                    <p className="text-destructive font-medium">Failed to load criteria</p>
125→                    <p className="text-sm text-muted-foreground mt-1">{String(error)}</p>
126→                </div>
127→            ) : (
128→                <CriteriaTable data={items} columns={columns} />
129→            )}
130→
131→            {/* Pagination */}
132→            {totalPages > 1 && (
133→                <div className="flex items-center justify-between">
134→                    <div className="text-sm text-muted-foreground">
